// Auto-generated from the exercise names, categories, and rep/hold defaults
// actually used across the Upper Body, Lower Body, and Full Body decks in
// src/hooks/use-workout.ts (Core deck excluded — locked, no cards yet). Powers
// the Custom Workout builder so the picker only ever offers exercises that are
// real and already illustrated elsewhere in the app.
//
// `bodyRegion` is computed with the same keyword rules as the app's own
// `getMovementCategory` (src/hooks/use-workout.ts) — Push/Pull/Dip collapse to
// "UpperBody", Legs to "LowerBody", Core stays "Core". This is a per-exercise
// classification (what the movement actually trains) and is intentionally
// more precise than `categories` (which existing decks happen to feature it) —
// e.g. "Plank" lives in the Full Body deck but is correctly tagged Core here.
import type { DeckCategory } from "@/types/workout";

export type MovementCategory = "Push" | "Pull" | "Dip" | "Core" | "Legs";
export type BodyRegion = "UpperBody" | "LowerBody" | "Core";

export interface CatalogExercise {
  name: string;
  /** Which existing decks feature this exercise. */
  categories: DeckCategory[];
  /** Push / Pull / Dip / Core / Legs — same classifier the real deck engine uses. */
  movementCategory: MovementCategory;
  /** Upper Body / Lower Body / Core — what the builder groups and filters by. */
  bodyRegion: BodyRegion;
  isIsometric: boolean;
  /** Suggested hold duration in seconds, editable by the user. Set when isIsometric. */
  defaultHoldSeconds?: number;
  /** Suggested rep count, editable by the user. Set when not isIsometric. */
  defaultReps?: number;
  /** True if this exercise is trained one side at a time (e.g. lunges, archer push-ups). */
  eachSide: boolean;
}

